using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;using System.Threading;
namespace FoolLauncher {public static class ModManagerTests {
 sealed class Quiet:IProgress<Update>{public void Report(Update u){}}
 static void Assert(bool value,string message){if(!value)throw new Exception(message);}
 public static void Run(string parent){var service=new PackService(Path.Combine(parent,"mod-manager"));var instance=new Instance{Id="selected",Name="Selected",Minecraft="1.20.1",Loader="fabric-loader 0.16.14"};string game=service.Game(instance),mods=Path.Combine(game,"mods");Directory.CreateDirectory(mods);string file=Path.Combine(mods,"example.jar");using(var zip=ZipFile.Open(file,ZipArchiveMode.Create))using(var w=new StreamWriter(zip.CreateEntry("fabric.mod.json").Open()))w.Write("{\"id\":\"example\",\"name\":\"Example\",\"version\":\"1.0\",\"description\":\"Description\"}");string hash;using(var s=SHA1.Create())using(var f=File.OpenRead(file))hash=BitConverter.ToString(s.ComputeHash(f)).Replace("-","").ToLowerInvariant();var entry=new PackFile{path="mods/example.jar",fileSize=new FileInfo(file).Length,hashes=new Dictionary<string,string>{{"sha1",hash}},downloads=new[]{"https://cdn.modrinth.com/data/fixture/example.jar"}};Json.Write(Path.Combine(service.Folder(instance),"launcher-instance.json"),instance);Json.Write(Path.Combine(service.Folder(instance),"pack-index.json"),new PackIndex{game="minecraft",formatVersion=1,name="Selected",versionId="1",dependencies=new Dictionary<string,string>{{"minecraft","1.20.1"},{"fabric-loader","0.16.14"}},files=new[]{entry}});var manager=new ModManager(service);var row=manager.List(instance,CancellationToken.None).Single();Assert(row.Name=="Example"&&row.Version=="1.0"&&row.Description=="Description","JAR metadata not read");manager.Change(instance,row,false,CancellationToken.None);Assert(!File.Exists(file)&&File.Exists(file+".disabled")&&service.Index(instance).files.Length==0,"Disable did not remove active file and manifest entry");Assert(service.Repair(instance,new Quiet(),CancellationToken.None).GetAwaiter().GetResult()==0&&!File.Exists(file),"Repair resurrected disabled mod");row=manager.List(instance,CancellationToken.None).Single();Assert(row.Disabled,"Disabled row missing");manager.Change(instance,row,false,CancellationToken.None);Assert(File.Exists(file)&&service.Index(instance).files.Length==1,"Enable did not restore original file/manifest");row=manager.List(instance,CancellationToken.None).Single();using(var c=new CancellationTokenSource()){c.Cancel();bool cancelled=false;try{manager.Change(instance,row,true,c.Token);}catch(OperationCanceledException){cancelled=true;}Assert(cancelled&&File.Exists(file)&&service.Index(instance).files.Length==1,"Cancelled deletion changed mod");}manager.Change(instance,row,true,CancellationToken.None);Assert(!File.Exists(file)&&service.Index(instance).files.Length==0&&Directory.GetFiles(Path.Combine(service.Folder(instance),"mod-backups"),"example.jar",SearchOption.AllDirectories).Any(),"Delete did not preserve backup or remove manifest");Assert(service.Repair(instance,new Quiet(),CancellationToken.None).GetAwaiter().GetResult()==0&&!File.Exists(file),"Repair resurrected deleted mod");Console.WriteLine("PASS: local JAR metadata, disable/enable manifest roundtrip, deleted-mod backup, repair persistence and cancelled mutation rollback.");}
}}
